@prefix mom: <https://rss-hydro.lu/ns/mom/> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/mom/run/2026030200/aggregation> ;
            sh:resultPath prov:used ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:QualifiedMinCountConstraintComponent ;
            sh:sourceShape [ sh:path prov:used ;
                    sh:qualifiedMinCount 1 ;
                    sh:qualifiedValueShape [ sh:class mom:WatershedCellLookup ] ] ] .

