@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/mom/run/2026030200/aggregation> ;
            sh:resultMessage "Cell lookup grid must match the gridSignature of the data aggregated" ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Cell lookup grid must match the gridSignature of the data aggregated" ;
                    sh:select """
            SELECT $this WHERE {
                $this <http://www.w3.org/ns/prov#used> ?lookup .
                ?lookup a <https://rss-hydro.lu/ns/mom/WatershedCellLookup> .
                FILTER NOT EXISTS {
                    ?lookup <http://www.w3.org/ns/prov#wasDerivedFrom>/<https://rss-hydro.lu/ns/mom/gridSignature> ?g .
                    $this <http://www.w3.org/ns/prov#used> ?data .
                    ?data <https://rss-hydro.lu/ns/mom/gridSignature> ?g .
                }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://rss-hydro.lu/ns/mom/rules/#gridMatchesLookup> ;
            sh:value <https://example.org/mom/run/2026030200/aggregation> ] .

